const sort = url.searchParams.get('sort')

const includeInkRegistry = include === 'ink_registry'
const sortByValue = sort === 'value'

const selectClause = includeInkRegistry
  ? '*, suppliers(id, name), locations(id, name), ink_registry:studio_ink_registry(id, batch_number, manufacture_date, expiry_date, reach_compliant, sds_url, product_code)'
  : '*, suppliers(id, name), locations(id, name)'

let query = supabase
  .from('inventory_items')
  .select(selectClause)
  .eq('studio_id', member.studio_id)
  .eq('is_active', is_active)

// Default order: name. Value sort applied post-query (computed column).
if (!sortByValue) {
  query = query.order('name')
}

if (category) query = query.eq('category', category as 'ink' | 'needle' | 'supply' | 'aftercare' | 'equipment' | 'apparel' | 'other')
if (supplier_id) query = query.eq('supplier_id', supplier_id)
if (location_id) query = query.eq('location_id', location_id)

const { data, error } = await query

if (error) {
  logger.error({ err: error }, 'inventory items GET failed')
  return Response.json({ error: 'Failed to fetch items' }, { status: 500 })
}

let items = data ?? []

if (stock_status === 'low') {
  items = items.filter(
    (i) => i.current_stock > 0 && i.current_stock <= i.min_threshold,
  )
} else if (stock_status === 'out') {
  items = items.filter((i) => i.current_stock <= 0)
}

// ?sort=value — ORDER BY (cost_per_unit_cents * current_stock) DESC
if (sortByValue) {
  items = [...items].sort(
    (a, b) =>
      b.cost_per_unit_cents * b.current_stock -
      a.cost_per_unit_cents * a.current_stock,
  )
}

// When include=ink_registry: Supabase returns an array for the relation because
// the FK is not a unique constraint (isOneToOne: false). Reduce to the most
// recent row per item, or null if none.
if (includeInkRegistry) {
  const normalized = (items as ItemWithInkRegistry[]).map((item) => {
    const raw = (item as unknown as Record<string, unknown>).ink_registry
    let resolved: InkRegistryPick | null = null
    if (Array.isArray(raw) && raw.length > 0) {
      // raw is InkRegistryPick[] from the nested select — pick most recent by created_at
      // The nested select doesn't include created_at, so we rely on insertion order (last element).
      // Supabase returns rows in insertion order by default; the last inserted is most recent.
      resolved = raw[raw.length - 1] as InkRegistryPick
    } else if (raw && !Array.isArray(raw)) {
      resolved = raw as InkRegistryPick
    }
    return { ...item, ink_registry: resolved }
  })
