import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { requireFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import type { PlanTier } from '@/lib/billing/feature-gate'

const RouteParamsSchema = z.object({
  id: z.string().uuid(),
})

const MAX_FILE_SIZE_BYTES = 10 * 1024 * 1024 // 10 MB
const ALLOWED_MIME_TYPE = 'application/pdf'
const SIGNED_URL_TTL_SECONDS = 31_536_000 // 1 year
const STORAGE_BUCKET = 'studio-ink-sds'

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const ip = getClientIp(request)
  const { success } = await apiRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const rawParams = await params
  const parsedParams = RouteParamsSchema.safeParse(rawParams)
  if (!parsedParams.success) {
    return Response.json({ error: 'Invalid ink registry id' }, { status: 400 })
  }
  const inkRegistryId = parsedParams.data.id

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return new Response('No studio membership', { status: 403 })

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const gate = requireFeature(plan, 'inventory')
  if (gate) return gate

  // Verify the ink registry row belongs to this studio
  const { data: registryRow, error: registryError } = await supabase
    .from('studio_ink_registry')
    .select('id')
    .eq('id', inkRegistryId)
    .eq('studio_id', member.studio_id)
    .single()

  if (registryError || !registryRow) {
    logger.warn(
      { inkRegistryId, studioId: member.studio_id },
      'sds upload: registry row not found or studio mismatch',
    )
    return new Response('Not found', { status: 404 })
  }

  // Parse multipart form data
  let formData: FormData
  try {
    formData = await request.formData()
  } catch (err) {
    logger.error({ err }, 'sds upload: failed to parse form data')
    return Response.json({ error: 'Invalid multipart form data' }, { status: 400 })
  }

  const file = formData.get('file')
  if (!(file instanceof File)) {
    return Response.json({ error: 'Missing file field' }, { status: 400 })
  }

  // Validate MIME type
  if (file.type !== ALLOWED_MIME_TYPE) {
    return Response.json(
      { error: `Only PDF files are accepted. Received: ${file.type}` },
      { status: 400 },
    )
  }

  // Validate file size
  if (file.size > MAX_FILE_SIZE_BYTES) {
    return Response.json(
      { error: 'File exceeds the 10 MB limit' },
      { status: 413 },
    )
  }

  // Build storage path: {studio_id}/{registry_id}-{timestamp}.pdf
  const timestamp = Date.now()
  const storagePath = `${member.studio_id}/${inkRegistryId}-${timestamp}.pdf`

  const arrayBuffer = await file.arrayBuffer()
  const fileBytes = new Uint8Array(arrayBuffer)

  const { error: uploadError } = await supabase.storage
    .from(STORAGE_BUCKET)
    .upload(storagePath, fileBytes, {
      contentType: ALLOWED_MIME_TYPE,
      upsert: false,
    })

  if (uploadError) {
    logger.error({ err: uploadError, storagePath }, 'sds upload: storage upload failed')
    return Response.json({ error: 'File upload failed' }, { status: 500 })
  }

  // Generate signed URL valid for 1 year
  const { data: signedUrlData, error: signedUrlError } = await supabase.storage
    .from(STORAGE_BUCKET)
    .createSignedUrl(storagePath, SIGNED_URL_TTL_SECONDS)

  if (signedUrlError || !signedUrlData?.signedUrl) {
    logger.error({ err: signedUrlError, storagePath }, 'sds upload: signed URL generation failed')
    // Clean up orphaned file
    await supabase.storage.from(STORAGE_BUCKET).remove([storagePath])
    return Response.json({ error: 'Failed to generate signed URL' }, { status: 500 })
  }

  const sdsUrl = signedUrlData.signedUrl

  // Persist signed URL on the registry row — RLS enforces studio ownership
  const { error: updateError } = await supabase
    .from('studio_ink_registry')
    .update({ sds_url: sdsUrl, updated_at: new Date().toISOString() })
    .eq('id', inkRegistryId)
    .eq('studio_id', member.studio_id)

  if (updateError) {
    logger.error({ err: updateError, inkRegistryId }, 'sds upload: DB update failed')
    // Clean up orphaned file
    await supabase.storage.from(STORAGE_BUCKET).remove([storagePath])
    return Response.json({ error: 'Failed to save SDS reference' }, { status: 500 })
  }

  logger.info(
    { inkRegistryId, studioId: member.studio_id, storagePath },
    'sds upload: success',
  )

  return Response.json({ sds_url: sdsUrl }, { status: 200 })
}

