const includeInkRegistry = include === 'ink_registry'
const sortByValue = sort === 'value'

let query = supabase
  .from('inventory_items')
  .select('*, suppliers(id, name), locations(id, name)')
  .eq('studio_id', member.studio_id)
  .eq('is_active', is_active)

// Default order: name. Value sort applied post-query (computed column).
if (!sortByValue) {
  query = query.order('name')
}

if (category) query = query.eq('category', category as 'ink' | 'needle' | 'supply' | 'aftercare' | 'equipment' | 'apparel' | 'other')
if (supplier_id) query = query.eq('supplier_id', supplier_id)
if (location_id) query = query.eq('location_id', location_id)

const { data, error } = await query

if (error) {
  logger.error({ err: error }, 'inventory items GET failed')
  return Response.json({ error: 'Failed to fetch items' }, { status: 500 })
}

let items = data ?? []

if (stock_status === 'low') {
  items = items.filter(
    (i) => i.current_stock > 0 && i.current_stock <= i.min_threshold,
  )
} else if (stock_status === 'out') {
  items = items.filter((i) => i.current_stock <= 0)
}

// ?sort=value — ORDER BY (cost_per_unit_cents * current_stock) DESC
if (sortByValue) {
  items = [...items].sort(
    (a, b) =>
      b.cost_per_unit_cents * b.current_stock -
      a.cost_per_unit_cents * a.current_stock,
  )
}

// ?include=ink_registry — fetch registry rows for these items in a separate query
// and merge. Two-query pattern avoids Supabase TS parser rejection of colon-alias
// syntax in the select string while preserving full type safety.
if (includeInkRegistry) {
  const itemIds = items.map((i) => i.id)

  if (itemIds.length === 0) {
    const empty: ItemWithInkRegistry[] = items.map((i) => ({ ...i, ink_registry: null }))
    return Response.json({ data: empty })
  }

  const { data: registryRows, error: registryError } = await supabase
    .from('studio_ink_registry')
    .select('id, batch_number, manufacture_date, expiry_date, reach_compliant, sds_url, product_code, item_id, created_at')
    .eq('studio_id', member.studio_id)
    .in('item_id', itemIds)
    .order('created_at', { ascending: false })

  if (registryError) {
    logger.error({ err: registryError }, 'inventory items GET: ink_registry join failed')
    return Response.json({ error: 'Failed to fetch ink registry data' }, { status: 500 })
  }

  // Build a map: item_id → most-recent registry row (already DESC ordered, so first match wins)
  const registryByItemId = new Map<string, InkRegistryPick>()
  for (const row of registryRows ?? []) {
    if (row.item_id && !registryByItemId.has(row.item_id)) {
      registryByItemId.set(row.item_id, {
        id: row.id,
        batch_number: row.batch_number,
        manufacture_date: row.manufacture_date,
        expiry_date: row.expiry_date,
        reach_compliant: row.reach_compliant,
        sds_url: row.sds_url,
        product_code: row.product_code,
      })
    }
  }

  const normalized: ItemWithInkRegistry[] = items.map((item) => ({
    ...item,
    ink_registry: registryByItemId.get(item.id) ?? null,
  }))

  return Response.json({ data: normalized })
}

return Response.json({ data: items })
